    db.prepare('INSERT INTO exercise_attendance (exercise_id, operator_id, callsign_suffix, entered_by) VALUES (?, ?, ?, ?)')
      .run(req.params.id, operator_id, callsign_suffix || null, admin.username);
    res.status(201).json({ success: true });
