   475→  const handleSubmit = (e: FormEvent) => {
   476→    e.preventDefault();
   477→    if (!form.callsign && !form.operator) return;
   478→    onSubmit(form);
   479→    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
   480→    setTimeout(() => callsignRef.current?.focus(), 50);
   481→  };
   482→
   483→  const handleDrop = (e: React.DragEvent) => {
   484→    e.preventDefault();
   485→    setDragOver(false);
   486→    if (dragReportId) {
   487→      const targetCode = bezirk.code === '??' ? null : bezirk.code;
   488→      onMoveToBezirk(dragReportId, targetCode);
   489→    }
   490→  };
   491→
   492→  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
   493→    if (!form.operator?.id) return;
   494→    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
   495→    if (value === original) return;
   496→    apiFetch(`/api/v1/operators/${form.operator.id}`, {
   497→      method: 'PATCH',
   498→      body: JSON.stringify({ [field]: value || null }),
   499→    }).then(() => {
   500→      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
