   506→      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
   507→      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
   508→      onDragLeave={() => setDragOver(false)}
