   510→    >
   511→      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
   512→        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   513→          {bezirk.code === '??' ? '??' : bezirk.code}
