   157→            repeater_id: repeaterId,
   158→            ...parsed,
   159→            notes: form.notes || null,
   160→            bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
   161→          }),
   162→        });
   163→        onReportCreated(report);
   164→      } catch (err: any) {
   165→        if (err.message?.includes('existiert')) {
   166→          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
   167→          if (existing) {
   168→            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   169→              method: 'PATCH',
   170→              body: JSON.stringify({ ...parsed, notes: form.notes || null, bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null }),
   171→            });
   172→            onReportUpdated(updated);
   173→          }
   174→        }
   175→      }
   176→    } catch {
   177→    }
   178→  };
   179→
   180→  const handleEdit = (report: any) => {
   181→    setEditingId(report.id);
   182→    setEditForm({
   183→      callsign: report.callsign,
   184→      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
   185→      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
   186→      notes: report.notes || '',
   187→      opName: report.operator_name || '',
   188→      opQth: report.operator_qth || '',
   189→      bezirkCode: report.bezirk_code || '',
   190→    });
   191→  };
   192→
   193→  const handleUpdate = async () => {
   194→    if (!editingId) return;
   195→    const parsed = parseRapport(editForm.rapport);
   196→    try {
   197→      // Save operator name/qth if changed
   198→      if (editForm.operator?.id) {
   199→        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
   200→        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
   201→        if (nameChanged || qthChanged) {
   202→          const patch: any = {};
   203→          if (nameChanged) patch.name = editForm.opName || null;
   204→          if (qthChanged) patch.qth = editForm.opQth || null;
   205→          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
   206→            method: 'PATCH',
   207→            body: JSON.stringify(patch),
   208→          });
   209→        }
   210→      }
   211→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
   212→        method: 'PATCH',
   213→        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null }),
   214→      });
   215→      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
   216→      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
   217→      onReportUpdated(updated);
   218→      setEditingId(null);
   219→    } catch {}
   220→  };
   221→
   222→  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
   223→    try {
   224→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
   225→        method: 'PATCH',
   226→        body: JSON.stringify({ bezirk_code: newBezirkCode }),
   227→      });
   228→      onReportUpdated(updated);
   229→    } catch {}
   230→  };
   231→
   232→  const handleDelete = async (reportId: number) => {
   233→    if (!confirm('Rapport löschen?')) return;
   234→    try {
   235→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
