    10→// Bund export (Bundesland-grouped)
    11→exportRouter.get('/exercises/:id/bund', (req, res) => {
    12→  const db = getDb();
    13→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id) as any;
    14→  if (!exercise) { res.status(404).json({ error: 'Nicht gefunden' }); return; }
    15→
    16→  const reports = db.prepare(`
    17→    SELECT sr.*, o.callsign, sr.bezirk_code, o.bundesland_code,
    18→      bl.name as bundesland_name, bz.name as bezirk_name,
    19→      r.short_name as repeater_name,
    20→      ep.abbreviation as ep_abbr
    21→    FROM signal_reports sr
    22→    JOIN operators o ON o.id = sr.operator_id
    23→    JOIN repeaters r ON r.id = sr.repeater_id
    24→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
    25→    LEFT JOIN bezirke bz ON bz.code = sr.bezirk_code
    26→    LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
    27→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
    28→    ORDER BY bl.sort_order, bz.code, o.callsign
    29→  `).all(req.params.id) as any[];
    30→
    31→  let text = `BOS-ARSA Übung — ${exercise.date}\n`;
    32→  text += `Auswertung OE-Link\n`;
    33→  text += '='.repeat(60) + '\n\n';
    34→
    35→  let currentBl = '';
    36→  let currentBz = '';
    37→  for (const r of reports) {
    38→    if (r.bundesland_name !== currentBl) {
    39→      currentBl = r.bundesland_name || 'Sonstige';
    40→      text += `\n── ${currentBl} ──\n`;
    41→      currentBz = '';
    42→    }
    43→    if (r.bezirk_code !== currentBz) {
    44→      currentBz = r.bezirk_code || '??';
    45→      text += `  [${currentBz}] ${r.bezirk_name || ''}\n`;
    46→    }
    47→    const rapport = r.readability && r.strength
    48→      ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}`
    49→      : '—';
    50→    const ep = r.ep_abbr ? ` ${r.ep_abbr}` : '';
    51→    text += `    ${r.callsign.padEnd(10)} ${r.repeater_name.padEnd(20)} ${rapport}${ep}\n`;
    52→  }
    53→
    54→  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    55→  res.setHeader('Content-Disposition', `attachment; filename="bos-arsa-oelink-${safeFilename(exercise.date)}.txt"`);
    56→  res.send(text);
    57→});
